import inspect

import pytest

import invoices.pricing as pricing


def test_apply_discount_example_1():
    assert pricing.apply_discount(200, 10) == 180.0

def test_apply_discount_example_2():
    assert pricing.apply_discount(50, 0) == 50.0

def test_apply_discount_example_3():
    with pytest.raises(ValueError):
        pricing.apply_discount(100, 150)

def test_apply_discount_signature():
    assert callable(pricing.apply_discount)
    assert list(inspect.signature(pricing.apply_discount).parameters) == ['amount', 'percent']

def test_bulk_tier_example_1():
    assert pricing.bulk_tier(9) == 0

def test_bulk_tier_example_2():
    assert pricing.bulk_tier(10) == 5

def test_bulk_tier_example_3():
    assert pricing.bulk_tier(50) == 10

def test_bulk_tier_signature():
